-- -----------------------------------
-- Table structure for `circle_master`
-- -----------------------------------

DROP TABLE IF EXISTS `circle_master`;
CREATE TABLE `circle_master` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `Circle` varchar(150) NOT NULL,
  `Zonal` varchar(150) NOT NULL,
  `created_at` datetime NOT NULL,
  `created_by` int(11) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=3282 DEFAULT CHARSET=latin1;

